# 클래스가 N 개일 때 혼동 행렬을 직접 채우는 함수
def confusion(actual, predicted, labels):
    idx = {lab: i for i, lab in enumerate(labels)}
    N = len(labels)
    M = [[0] * N for _ in range(N)]
    for a, p in zip(actual, predicted):
        M[idx[p]][idx[a]] += 1        # 가로줄 = 예측, 세로줄 = 정답
    return M

labels = ["개", "고양이", "새", "물고기"]          # N = 4 → 4×4
actual    = ["개", "개", "고양이", "새", "물고기", "고양이"]
predicted = ["개", "고양이", "고양이", "새", "새", "고양이"]
for lab, row in zip(labels, confusion(actual, predicted, labels)):
    print(f"예측 {lab:4s}", row)
